 try:
  a=os.fstat(fd);assert stat.S_ISREG(a.st_mode)and a.st_nlink==1 and a.st_size<=maximum
  chunks=[];size=0
  while True:
   block=os.read(fd,65536)
   if not block:break
   size+=len(block);assert size<=maximum;chunks.append(block)
  b=os.fstat(fd);c=p.lstat();assert all(getattr(a,k)==getattr(b,k)==getattr(c,k)for k in FIELDS)and size==a.st_size
  raw=b''.join(chunks);return raw,dict(path=str(p),sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw),identity={k:getattr(b,k)for k in FIELDS})
 finally:os.close(fd)
